function icon(name, cls = '') {
  const el = document.createElement('span');
  el.className = 'ico ' + cls;
  el.innerHTML = ICONS[name] || '';
  return el;
}

function zoneSelect(name, current) {
  const zones = (state.meta && state.meta.zones && state.meta.zones.length)
    ? state.meta.zones
    : ['Zona Norte', 'Zona Centro', 'Zona Sur', 'Zona Oriente', 'Zona Occidente'];
  return h('select', { name, required: true },
    zones.map(z => h('option', { value: z, selected: z === current }, z))
  );
}

/* ---------- API ---------- */
const API = {
  token: localStorage.getItem('fy_token'),
  setToken(t) {
    this.token = t;
    if (t) localStorage.setItem('fy_token', t); else localStorage.removeItem('fy_token');
  },
  async call(method, path, body) {
    const headers = { 'Content-Type': 'application/json' };
    if (this.token) headers.Authorization = 'Bearer ' + this.token;
    const res = await fetch('/api' + path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
    let data = null;
    try { data = await res.json(); } catch (e) { /* sin cuerpo */ }
    if (!res.ok) {
      const msg = (data && data.error) || 'No pudimos completar la acción. Intenta de nuevo.';
      const lost = res.status === 401 || (res.status === 403 && /deshabilitada/.test(msg));
      if (lost && this.token) { this.setToken(null); state.user = null; if (typeof renderApp === 'function') renderApp(); }
      throw new Error(msg);
    }
    return data;
  },
  get(path) { return this.call('GET', path); },
  post(path, body) { return this.call('POST', path, body === undefined ? {} : body); },
  put(path, body) { return this.call('PUT', path, body); }
};

/* ---------- DOM ---------- */
function h(tag, props, ...kids) {
  const el = document.createElement(tag);
  if (props) {
    for (const [k, v] of Object.entries(props)) {
      if (v == null || v === false) continue;
      if (k === 'class') el.className = v;
      else if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
      else if (k in el && k !== 'list') el[k] = v;
      else el.setAttribute(k, v === true ? '' : v);
    }
  }
  kids.flat(Infinity).forEach(c => {
    if (c == null || c === false) return;
    el.append(c.nodeType ? c : document.createTextNode(String(c)));
  });
  return el;
}

function field(label, input, hint) {
  return h('label', { class: 'field' },
    h('span', { class: 'field-label' }, label),
    input,
    hint && h('small', { class: 'muted' }, hint));
}

function notice(kind, title, text) {
  return h('div', { class: 'notice ' + kind, role: 'status' }, h('strong', null, title), text && h('span', null, text));
}

function empty(title, text, action) {
  return h('div', { class: 'empty' }, h('h3', null, title), text && h('p', { class: 'muted' }, text), action);
}

