/* ---------- Formato ---------- */
const moneyFmt = new Intl.NumberFormat(CONFIG.locale, { style: 'currency', currency: CONFIG.currency, maximumFractionDigits: 0 });
const money = n => (n == null ? '' : moneyFmt.format(n));

function relTime(iso) {
  if (!iso) return '';
  const s = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 45) return 'hace un momento';
  const m = Math.round(s / 60);
  if (m < 60) return 'hace ' + m + ' min';
  const hr = Math.round(m / 60);
  if (hr < 24) return 'hace ' + hr + ' h';
  const d = Math.round(hr / 24);
  return 'hace ' + d + (d === 1 ? ' día' : ' días');
}

function clock(iso) {
  const d = new Date(iso);
  const t = d.toLocaleTimeString(CONFIG.locale, { hour: '2-digit', minute: '2-digit' });
  if (d.toDateString() === new Date().toDateString()) return t;
  return d.toLocaleDateString(CONFIG.locale, { day: 'numeric', month: 'short' }) + ', ' + t;
}

const statusLabel = s => state.meta.statuses[s] || s;

function statusTone(s) {
  if (s === 'ENTREGADO') return 'done';
  if (['CANCELADA', 'RECHAZADA', 'VENCIDA', 'CON_INCIDENCIA'].includes(s)) return 'bad';
  if (['SOLICITUD_ENVIADA', 'BUSCANDO_FARMACIA', 'PRECIO_POR_ACEPTAR', 'PEDIDO_LISTO', 'BUSCANDO_REPARTIDOR'].includes(s)) return 'wait';
  return 'go';
}

const badge = s => h('span', { class: 'badge tone-' + statusTone(s) }, statusLabel(s));

/* ---------- Avisos, diálogos y acciones ---------- */
function toast(msg, kind = 'ok') {
  const iconSpan = h('span', { class: 'toast-ico', 'aria-hidden': 'true' }, kind === 'error' ? '⚠️' : '✓');
  const textSpan = h('span', { class: 'toast-msg' }, msg);
  const t = h('div', { class: 'toast ' + kind, role: kind === 'error' ? 'alert' : 'status' }, iconSpan, textSpan);
  t.style.cursor = 'pointer';
  t.title = 'Haz clic para cerrar';
  t.addEventListener('click', () => {
    t.classList.add('out');
    setTimeout(() => t.remove(), 250);
  });

  const activeDialog = document.querySelector('dialog[open]');
  let container;
  if (activeDialog) {
    container = activeDialog.querySelector('.dialog-toasts');
    if (!container) {
      container = h('div', { class: 'toasts dialog-toasts', 'aria-live': 'polite' });
      activeDialog.append(container);
    }
  } else {
    container = document.getElementById('toasts');
  }

  if (container) container.append(t);

  setTimeout(() => t.classList.add('out'), 3800);
  setTimeout(() => t.remove(), 4400);
}

function openDialog(content, opts = {}) {
  const d = h('dialog', { class: 'sheet' + (opts.wide ? ' wide' : '') + (opts.drawer ? ' drawer' : '') }, content);
  d.addEventListener('close', () => { d.remove(); if (opts.onClose) opts.onClose(); });
  d.addEventListener('click', e => { if (e.target === d) d.close(); });
  document.body.append(d);
  d.showModal();
  return d;
}

function confirmBox({ title, message, ok = 'Confirmar', cancel = 'Volver', danger = false }) {
  return new Promise(resolve => {
    let result = false;
    const d = openDialog(
      h('div', { class: 'sheet-body narrow' },
        h('h3', null, title),
        message && h('p', { class: 'muted' }, message),
        h('div', { class: 'actions' },
          h('button', { class: 'btn ghost', type: 'button', onclick: () => d.close() }, cancel),
          h('button', { class: 'btn ' + (danger ? 'danger' : 'primary'), type: 'button', onclick: () => { result = true; d.close(); } }, ok))),
      { onClose: () => resolve(result) });
  });
}

function promptBox({ title, message, label, placeholder = '', ok = 'Enviar', minLength = 5, multiline = true }) {
  return new Promise(resolve => {
    let result = null;
    const input = multiline
      ? h('textarea', { rows: 4, required: true, minLength, maxLength: 500, placeholder })
      : h('input', { required: true, minLength, placeholder });
    const form = h('form', {
      class: 'sheet-body narrow',
      onsubmit: e => { e.preventDefault(); result = input.value.trim(); d.close(); }
    },
      h('h3', null, title),
      message && h('p', { class: 'muted' }, message),
      field(label, input),
      h('div', { class: 'actions' },
        h('button', { class: 'btn ghost', type: 'button', onclick: () => d.close() }, 'Volver'),
        h('button', { class: 'btn primary', type: 'submit' }, ok)));
    const d = openDialog(form, { onClose: () => resolve(result) });
    input.focus();
  });
}

/** Ejecuta una acción deshabilitando el botón y mostrando el resultado. */
async function act(btn, fn, success) {
  if (btn) { btn.disabled = true; btn.classList.add('busy'); }
  try {
    const r = await fn();
    if (success) toast(success);
    return r;
  } catch (e) {
    toast(e.message, 'error');
    return undefined;
  } finally {
    if (btn) { btn.disabled = false; btn.classList.remove('busy'); }
  }
}

const refreshAll = () => document.dispatchEvent(new Event('fy:refresh'));

/**
 * Contenedor que se actualiza solo: consulta cada pocos segundos y redibuja
 * únicamente si los datos cambiaron. Se detiene al salir del DOM.
 */
function live(fetcher, draw, every = 5000) {
  const box = h('div', { class: 'live' }, h('div', { class: 'loading', role: 'status', 'aria-label': 'Cargando' }, skeleton()));
  let sig = null, busy = false;
  const tick = async force => {
    if (busy && !force) return;
    busy = true;
    try {
      const data = await fetcher();
      const s = JSON.stringify(data);
      if (force || s !== sig) { sig = s; box.replaceChildren(draw(data)); }
    } catch (e) {
      if (sig === null) box.replaceChildren(notice('bad', 'No pudimos cargar la información', e.message));
    } finally { busy = false; }
  };
  const onRefresh = () => tick(true);
  document.addEventListener('fy:refresh', onRefresh);
  tick(true);
  const timer = setInterval(() => {
    if (!document.body.contains(box)) {
      clearInterval(timer);
      document.removeEventListener('fy:refresh', onRefresh);
      return;
    }
    if (!document.querySelector('dialog[open] form')) tick(false);
  }, every);
  return box;
}

function tabs(items, start = 0) {
  const panel = h('div', { class: 'panel', role: 'tabpanel' });
  const bar = h('div', { class: 'tabs', role: 'tablist' });
  const buttons = items.map((it, i) => h('button', { class: 'tab', role: 'tab', type: 'button', onclick: () => select(i) }, it.label));
  function select(i) {
    buttons.forEach((b, j) => { b.classList.toggle('on', i === j); b.setAttribute('aria-selected', String(i === j)); });
    panel.replaceChildren(items[i].render());
  }
  bar.append(...buttons);
  select(start);
  const root = h('div', { class: 'tabs-root' }, bar, panel);
  root.select = select;
  return root;
}

/** Interruptor accesible (checkbox con aspecto de switch). */
function switchControl(checked, onChange, label) {
  const input = h('input', { type: 'checkbox', class: 'switch-input', 'aria-label': label, checked, onchange: () => onChange(input) });
  return h('span', { class: 'switch' }, input, h('span', { class: 'switch-track' }));
}


/* ---------- Carga con esqueletos ---------- */
function skeleton(n = 3) {
  return h('div', { class: 'skeleton-list', 'aria-hidden': 'true' }, Array.from({ length: n }, () => h('div', { class: 'skeleton' })));
}

/* ---------- Sonido de avisos (se puede apagar desde la barra superior) ---------- */
const sound = {
  get on() { return localStorage.getItem('fy_sound') !== 'off'; },
  set on(v) { localStorage.setItem('fy_sound', v ? 'on' : 'off'); }
};
let audioCtx = null;
function beep() {
  if (!sound.on) return;
  try {
    audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
    const t = audioCtx.currentTime;
    [660, 880].forEach((f, i) => {
      const o = audioCtx.createOscillator();
      const g = audioCtx.createGain();
      const at = t + i * 0.14;
      o.type = 'sine';
      o.frequency.value = f;
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(0.18, at + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, at + 0.2);
      o.connect(g);
      g.connect(audioCtx.destination);
      o.start(at);
      o.stop(at + 0.22);
    });
  } catch (e) { /* el navegador puede bloquear el audio hasta que haya una interacción */ }
}

/* ---------- Tiempos en vivo ---------- */
function fmtSpan(sec) {
  sec = Math.max(0, Math.floor(sec));
  const hh = Math.floor(sec / 3600), mm = Math.floor((sec % 3600) / 60), ss = sec % 60;
  return (hh ? hh + ':' + String(mm).padStart(2, '0') : mm) + ':' + String(ss).padStart(2, '0');
}

/** Texto que se actualiza cada segundo y se detiene solo al salir de la pantalla. */
function ticking(compute) {
  const span = h('span', { class: 'ticker' }, compute());
  let idle = 0;
  const timer = setInterval(() => {
    if (document.body.contains(span)) { span.dataset.seen = '1'; span.textContent = compute(); return; }
    if (span.dataset.seen || ++idle > 5) clearInterval(timer);
  }, 1000);
  return span;
}
const elapsedEl = iso => ticking(() => fmtSpan((Date.now() - new Date(iso).getTime()) / 1000));
const countdownEl = (iso, done) => ticking(() => {
  const s = (new Date(iso).getTime() - Date.now()) / 1000;
  return s > 0 ? fmtSpan(s) : done;
});
const hhmm = iso => new Date(iso).toLocaleTimeString(CONFIG.locale, { hour: '2-digit', minute: '2-digit' });

/* Navegación lateral común para paneles internos. */
function sideNavigation(items, start = 0) {
  const nav = h('aside', { class: 'side-nav', 'aria-label': 'Navegación del panel' });
  const buttons = items.map((it, i) => h('button', { class: 'side-nav-item', type: 'button', 'aria-current': i === start ? 'page' : 'false', onclick: () => select(i) },
    h('span', { class: 'side-nav-icon', 'aria-hidden': 'true' }, icon(it.icon || 'circle')), h('span', { class: 'side-nav-label' }, it.label)));
  const panel = h('section', { class: 'side-nav-content', 'aria-live': 'polite' });
  function select(i) {
    buttons.forEach((b, j) => { b.classList.toggle('active', i === j); b.setAttribute('aria-current', i === j ? 'page' : 'false'); });
    panel.replaceChildren(items[i].render());
  }
  nav.append(h('nav', { class: 'side-nav-items' }, buttons));
  const root = h('div', { class: 'side-nav-layout' }, nav, panel);
  root.select = select;
  select(start);
  return root;
}

function movementHistory(endpoint) {
  return live(() => API.get(endpoint), movements => {
    if (!movements.length) return empty('Todavía no hay movimientos', 'Las acciones importantes que realices aparecerán aquí con fecha, hora y pedido relacionado.');
    return h('div', { class: 'table-wrap movement-table' }, h('table', { class: 'users' },
      h('thead', null, h('tr', null, h('th', null, 'Acción'), h('th', null, 'Pedido'), h('th', null, 'Fecha y hora'))),
      h('tbody', null, movements.map(m => h('tr', null,
        h('td', null, h('strong', null, movementTypeLabel(m.type)), h('small', { class: 'block-line muted movement-description' }, m.description || 'Sin descripción')),
        h('td', null, m.orderCode || '—'), h('td', null, formatMovementDate(m.createdAt)))))));
  });
}

function metricCard(label, value, detail, iconName) {
  return h('article', { class: 'metric-card' }, h('span', { class: 'metric-icon', 'aria-hidden': 'true' }, icon(iconName || 'chart-no-axes-column-increasing')),
    h('div', { class: 'metric-copy' }, h('span', { class: 'metric-label' }, label), h('strong', { class: 'metric-value' }, value), detail ? h('small', { class: 'muted' }, detail) : null));
}

function partnerActivity(endpoint) {
  return live(() => API.get(endpoint), data => {
    const rows = data.recentOrders || [];
    if (!rows.length) return empty('Aún no hay actividad', 'Cuando recibas y gestiones pedidos, verás aquí los movimientos recientes.');
    return h('div', { class: 'list' }, rows.map(o => h('article', { class: 'activity-row' },
      h('div', null, h('strong', null, o.code), h('small', { class: 'block-line muted' }, formatMovementDate(o.createdAt)), o.zone ? h('small', { class: 'block-line muted' }, o.zone) : null),
      h('div', { class: 'activity-right' }, badge(o.status), o.total != null ? h('strong', null, money(o.total)) : null))));
  });
}
